67: /// Where `taken_at` came from — the info panel shows the sentence (§8.3).
68: #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
69: pub enum TakenSource {
70:     ExifOriginal,
71:     ExifDigitized,
72:     Exif,
73:     Filename,
74:     Container,
75:     FileModified,
76:     #[default]
77:     Unknown,
78: }
