198:             EditOp::Filter { before, after, .. } => (before.clone(), after.clone()),
199:             EditOp::Rating { before, after, .. } => (before.to_string(), after.to_string()),
200:             EditOp::Favourite { before, after, .. } => (before.to_string(), after.to_string()),
201:             EditOp::Tag { before, after, .. } => (serde_json::to_string(before).unwrap_or_default(), serde_json::to_string(after).unwrap_or_default()),
202:             EditOp::Caption { before, after, .. } => (before.clone(), after.clone()),
203:             EditOp::Trash { target } => ("present".into(), format!("trashed:{target}")),
204:             EditOp::Export { written, .. } => ("none".into(), written.join(",")),
205:             EditOp::FlipH { .. } | EditOp::FlipV { .. } | EditOp::Reset { .. } => ("old".into(), "new".into()),
