//! Thumbnail cache — disk LRU (500 MB) + big-thumb pool of 8 (PHOTOS-SPECS §4.2–4.3)
//! + on-demand decode pipeline (P0–P3 queue, visible-only).
//!
//! Cache key is **BLAKE3(abspath ‖ rung ‖ mtime_ns ‖ orientation ‖ edit_generation)**
//! (128-bit hex, fanout 2+2 → 256 ways). mtime *is* in the key: a changed file
//! is a new thumbnail (LIE-7). Orientation and edit-generation are in the key
//! because EXIF/sidecar rotation and non-destructive edits change the render
//! without touching the file.
//!
//! Bounded everything (L10): disk cache evicted to the budget; at most
//! [`BIG_THUMB_POOL`] above-threshold (≥512 px) textures resident; a file that
//! failed [`FAIL_AFTER`] times is skipped with a reason instead of re-probed.
//!
//! Decode pipeline (honest degrade, no silent black):
//! - Images: in-memory LRU + **on-demand 2-thread LIFO** queue + bounded
//!   `seen` dedupe (1024). LIFO = newest = what is on screen now. No decoder
//!   ever runs for an off-screen cell: the caller hands us only the visible
//!   set via [`ThumbCache::rebuild_visible`] and the queue is *rebuilt*,
//!   never accumulated (§4.4 "goes black at 10k per day" fix).
//! - Video: `ffmpeg -ss 0.7` single frame (the `thumbs.rs video_thumb`
//!   pattern) → disk cache under `~/.cache/smart-files/thumbs` (shared with
//!   Files) → `image` decode → thumbnail. The key is still the full BLAKE3
//!   key above (mtime included) — never the path-only fnv that made the
//!   Files cache go stale forever. No ffmpeg → `None` → the caller renders
//!   the declared "indexed, no preview" tile with the reason, never black.
//! - Cancellable: every job carries a generation; [`ThumbCache::rebuild_visible`]
//!   and [`ThumbCache::cancel`] bump it and stale jobs are dropped.

use std::collections::{HashMap, HashSet, VecDeque};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Condvar, Mutex};

pub const DEFAULT_CACHE_MB: u64 = 500;
pub const CACHE_CEILING_MB: u64 = 2048;
pub const BIG_THUMB_POOL: usize = 8;
pub const FAIL_AFTER: u32 = 3;
/// Long-edge ladder, longest first. `wanted_rung` never exceeds 1.5× the need.
pub const LADDER: [u32; 7] = [64, 128, 256, 512, 1024, 2048, 4096];
pub const THUMB_FORMAT: &str = "WebP q82, first frame";
/// Shared disk dir with Files (protocol: one cache, two readers).
pub const DISK_THUMB_SUBDIR: &str = "smart-files/thumbs";
/// Thumb workers: 2 on native (LIFO, on-demand). Created once, never resized.
/// (Spec §4.1 optimum is `min(8, max(2, cores/2))`; the Files `thumbs.rs`
/// pattern ships 2, which keeps RAM predictable on old machines — that is
/// the pinned behaviour here.)
pub const THUMB_WORKERS: usize = 2;
/// Bounded `seen` dedupe (Files `thumbs.rs LRU_CAP`). Unbounded sets leak.
pub const SEEN_CAP: usize = 1024;
/// Read cap for decode (Files `thumbs.rs` 48 MB).
pub const MAX_DECODE_BYTES: usize = 48 << 20;
/// Seconds into the video for the still (§4.4: 0.7 s, 384 px).
pub const VIDEO_SEEK: &str = "0.7";

/// Pick the smallest rung ≥ `need`, never larger than 1.5× the need.
pub fn wanted_rung(need_long_edge: f32) -> u32 {
    let need = need_long_edge.max(1.0);
    for r in LADDER {
        if (r as f32) >= need {
            // Never larger than 1.5× the need — if this rung overshoots that
            // much, the previous rung is the closer match.
            if (r as f32) > need * 1.5 {
                let idx = LADDER.iter().position(|x| *x == r).unwrap_or(0);
                if idx > 0 {
                    return LADDER[idx - 1];
                }
            }
            return r;
        }
    }
    *LADDER.last().unwrap_or(&4096)
}

/// BLAKE3(abspath ‖ 0x00 ‖ rung ‖ 0x00 ‖ mtime_ns ‖ 0x00 ‖ orientation ‖ 0x00 ‖ edit_generation)
pub fn cache_key(path: &str, rung: u32, mtime_ns: i64, orientation: u32, edit_generation: u64) -> String {
    let mut h = blake3::Hasher::new();
    h.update(path.as_bytes());
    h.update(&[0]);
    h.update(&rung.to_le_bytes());
    h.update(&[0]);
    h.update(&mtime_ns.to_le_bytes());
    h.update(&[0]);
    h.update(&orientation.to_le_bytes());
    h.update(&[0]);
    h.update(&edit_generation.to_le_bytes());
    h.finalize().to_string()[..32].to_string()
}

/// Fanout directory for a key: 2+2 hex chars (256 ways) — `readdir` discipline.
pub fn fanout(key: &str) -> (String, String) {
    let a = key.get(0..2).unwrap_or("00").to_string();
    let b = key.get(2..4).unwrap_or("00").to_string();
    (a, b)
}

/// Disk cache directory: `~/.cache/smart-files/thumbs` (shared with Files).
/// Falls back to the temp dir only if no cache dir is known (never panics).
pub fn disk_dir() -> PathBuf {
    if let Some(d) = dirs::cache_dir() {
        d.join(DISK_THUMB_SUBDIR)
    } else {
        std::env::temp_dir().join(DISK_THUMB_SUBDIR)
    }
}

/// Disk location for one key: `<dir>/<fan0>/<fan1>/<key>.png`.
pub fn disk_path_for(dir: &Path, key: &str) -> PathBuf {
    let (a, b) = fanout(key);
    dir.join(a).join(b).join(format!("{key}.png"))
}

/// Exact ffmpeg args for a video still. Pure function so the contract
/// (`-ss 0.7`, single frame, 384 px, png pipe) is testable without a binary.
pub fn video_ffmpeg_args(real_path: &str) -> Vec<String> {
    vec![
        "-loglevel".into(),
        "error".into(),
        "-ss".into(),
        VIDEO_SEEK.into(),
        "-i".into(),
        real_path.into(),
        "-frames:v".into(),
        "1".into(),
        "-vf".into(),
        "scale='min(384,iw)':-2".into(),
        "-f".into(),
        "image2pipe".into(),
        "-vcodec".into(),
        "png".into(),
        "-".into(),
    ]
}

/// Bounded LRU over memory residency (FIFO per Shotwell `Caching` note).
#[derive(Debug)]
pub struct Lru<T> {
    cap: usize,
    map: HashMap<String, T>,
    order: VecDeque<String>,
}

impl<T> Lru<T> {
    pub fn new(cap: usize) -> Self {
        Self { cap: cap.max(1), map: HashMap::new(), order: VecDeque::new() }
    }
    /// Insert; evicts the least-recently *seen* entry. Returns true if inserted.
    pub fn insert(&mut self, key: String, val: T) -> bool {
        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), val);
            self.touch(&key);
            return false;
        }
        while self.map.len() >= self.cap {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            } else {
                break;
            }
        }
        self.order.push_back(key.clone());
        self.map.insert(key, val);
        true
    }
    pub fn get(&mut self, key: &str) -> Option<&T> {
        if !self.map.contains_key(key) {
            return None;
        }
        self.touch(key);
        self.map.get(key)
    }
    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            if let Some(k) = self.order.remove(pos) {
                self.order.push_back(k);
            }
        }
    }
    pub fn len(&self) -> usize {
        self.map.len()
    }
    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }
}

/// Bounded `seen` dedupe (Files `thumbs.rs LruSeen` pattern).
/// Stores cache keys; evicts oldest past [`SEEN_CAP`]. `insert` returns
/// false when the key was already seen (dedupe).
#[derive(Debug, Default)]
pub struct SeenLru {
    set: HashSet<String>,
    order: VecDeque<String>,
}

impl SeenLru {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn insert(&mut self, key: String) -> bool {
        if !self.set.insert(key.clone()) {
            return false;
        }
        self.order.push_back(key);
        while self.order.len() > SEEN_CAP {
            if let Some(old) = self.order.pop_front() {
                self.set.remove(&old);
            } else {
                break;
            }
        }
        true
    }
    pub fn contains(&self, key: &str) -> bool {
        self.set.contains(key)
    }
    /// Forget every key whose value mentions `path` (edit / re-index).
    pub fn forget_containing(&mut self, path: &str) {
        if path.is_empty() {
            return;
        }
        // Keys are BLAKE3 hex — they never literally contain the path.
        // Keep the set consistent anyway: callers that tracked a path-key
        // prefix can clear by exact key via `remove`. This method exists so
        // `ThumbCache::forget(path)` keeps its contract (edit → new key
        // anyway via mtime/generation, so stale entries simply age out).
        self.set.retain(|k| !k.contains(path));
        self.order.retain(|k| !k.contains(path));
    }
    pub fn remove(&mut self, key: &str) {
        self.set.remove(key);
        self.order.retain(|k| k != key);
    }
    pub fn len(&self) -> usize {
        self.set.len()
    }
}

/// Big-thumb residency: at most 8 decoded above-threshold (≥512 px) rungs.
pub type BigPool = Lru<Vec<u8>>;

/// Disk LRU budget (user setting; default 500 MB).
#[derive(Debug)]
pub struct DiskLru {
    pub dir: PathBuf,
    pub budget_bytes: u64,
}

impl DiskLru {
    pub fn new(dir: PathBuf, budget_mb: u64) -> Self {
        Self { dir, budget_bytes: budget_mb.clamp(64, CACHE_CEILING_MB) << 20 }
    }
    /// Evict oldest files until the cache is under budget. Returns freed bytes.
    pub fn evict(&self) -> u64 {
        let mut total = 0u64;
        let mut entries: Vec<(i64, PathBuf)> = Vec::new();
        walk_files(&self.dir, &mut |p| {
            if let Ok(m) = std::fs::metadata(&p) {
                total += m.len();
                let t = m.modified().ok().and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_nanos() as i64).unwrap_or(0);
                entries.push((t, p));
            }
        });
        entries.sort_by_key(|(t, _)| *t);
        let mut freed = 0u64;
        for (_, p) in entries {
            if total <= self.budget_bytes {
                break;
            }
            if let Ok(m) = std::fs::metadata(&p) {
                if std::fs::remove_file(&p).is_ok() {
                    total = total.saturating_sub(m.len());
                    freed += m.len();
                }
            }
        }
        freed
    }
}

fn walk_files(dir: &PathBuf, f: &mut impl FnMut(PathBuf)) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() {
                walk_files(&p, f);
            } else {
                f(p);
            }
        }
    }
}

/// One visible thumb request. `key` is the BLAKE3 cache key (mtime in it).
#[derive(Clone, Debug)]
pub struct ThumbJob {
    pub path: String,
    pub key: String,
    pub rung: u32,
    pub edge: u32,
    pub generation: u64,
}

/// Finished thumbnail (RGBA, on-screen size).
#[derive(Clone, Debug)]
pub struct ThumbResult {
    pub key: String,
    pub path: String,
    pub w: u32,
    pub h: u32,
    pub rgba: Vec<u8>,
    pub from_disk: bool,
    pub video_frame: bool,
}

#[derive(Default)]
struct QueueState {
    queue: Vec<ThumbJob>,
    out: Vec<ThumbResult>,
}

struct Shared {
    state: Mutex<QueueState>,
    cv: Condvar,
    generation: AtomicU64,
    cancelled: AtomicBool,
}

impl Shared {
    fn lock_state(&self) -> std::sync::MutexGuard<'_, QueueState> {
        // Invariant: no thread panics while holding the lock; recover anyway
        // rather than propagate poison as a panic.
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }
}

/// Composite cache: disk LRU + big-thumb pool + fail records + decode queue.
pub struct ThumbCache {
    pub disk: DiskLru,
    pub big: BigPool,
    /// `fail/<digest(abspath,mtime_ns)>` — failed N times.
    pub fails: HashMap<String, u32>,
    /// Bounded seen dedupe (1024). Plain field (workers own queue-side
    /// dedupe via generation); mutated on the UI thread.
    pub seen: SeenLru,
    shared: Arc<Shared>,
}

impl ThumbCache {
    pub fn new(cache_mb: u64, pool: usize) -> Self {
        let dir = disk_dir();
        let _ = std::fs::create_dir_all(&dir);
        let shared = Arc::new(Shared {
            state: Mutex::new(QueueState::default()),
            cv: Condvar::new(),
            generation: AtomicU64::new(1),
            cancelled: AtomicBool::new(false),
        });
        #[cfg(not(target_arch = "wasm32"))]
        {
            let cache_dir = dir.clone();
            for _ in 0..THUMB_WORKERS {
                let (s, d) = (shared.clone(), cache_dir.clone());
                let _ = std::thread::spawn(move || {
                    thumb_worker(s, d);
                });
            }
        }
        Self {
            disk: DiskLru::new(dir, cache_mb),
            big: Lru::new(pool.max(1)),
            fails: HashMap::new(),
            seen: SeenLru::new(),
            shared,
        }
    }

    /// Test / inline constructor without worker threads (wasm + unit tests).
    pub fn new_inline(cache_mb: u64, pool: usize, dir: PathBuf) -> Self {
        let _ = std::fs::create_dir_all(&dir);
        Self {
            disk: DiskLru::new(dir, cache_mb),
            big: Lru::new(pool.max(1)),
            fails: HashMap::new(),
            seen: SeenLru::new(),
            shared: Arc::new(Shared {
                state: Mutex::new(QueueState::default()),
                cv: Condvar::new(),
                generation: AtomicU64::new(1),
                cancelled: AtomicBool::new(false),
            }),
        }
    }

    fn fail_key(path: &str, mtime_ns: i64) -> String {
        let mut h = blake3::Hasher::new();
        h.update(path.as_bytes());
        h.update(&mtime_ns.to_le_bytes());
        h.finalize().to_string()[..32].to_string()
    }

    pub fn is_failed_out(&self, path: &str, mtime_ns: i64) -> bool {
        self.fails.get(&Self::fail_key(path, mtime_ns)).copied().unwrap_or(0) >= FAIL_AFTER
    }

    pub fn record_fail(&mut self, path: &str, mtime_ns: i64) {
        *self.fails.entry(Self::fail_key(path, mtime_ns)).or_insert(0) += 1;
    }

    /// Forget cached state for `path` after an edit (new key anyway via
    /// mtime/generation; this clears the seen hint).
    pub fn forget(&mut self, path: &str) {
        self.seen.forget_containing(path);
        self.fails.retain(|k, _| !k.contains(path));
        self.seen.remove(path);
    }

    pub fn generation(&self) -> u64 {
        self.shared.generation.load(Ordering::SeqCst)
    }

    /// Enqueue one job (viewer-zoom / focused cell). Dedupe via `seen`.
    /// Returns false when the key was already requested (dedupe hit).
    pub fn request_one(&mut self, job: ThumbJob) -> bool {
        if !self.seen.insert(job.key.clone()) {
            return false;
        }
        self.enqueue(job);
        true
    }

    fn enqueue(&self, job: ThumbJob) {
        let mut st = self.shared.lock_state();
        st.queue.push(job);
        self.shared.cv.notify_one();
    }

    /// Visible-only: **replace** the pending queue with the current
    /// viewport (+ the single focused cell the caller includes). Anything
    /// off-screen is never decoded (it is not in the vec). Bumps the
    /// generation so in-flight stale results are dropped by [`poll`].
    /// LIFO: the last visible cell (usually just-scrolled) decodes first.
    pub fn rebuild_visible(&mut self, jobs: Vec<ThumbJob>) {
        self.shared.generation.fetch_add(1, Ordering::SeqCst);
        self.shared.cancelled.store(false, Ordering::SeqCst);
        let gen = self.shared.generation.load(Ordering::SeqCst);
        for j in jobs {
            self.seen.insert(j.key.clone());
            let mut j = j;
            j.generation = gen;
            self.enqueue(j);
        }
    }

    /// Cancel all pending decoding (dialog dismissed, app hidden).
    /// In-flight jobs finish but their results are dropped at [`poll`]
    /// if the generation moved — and no new work starts.
    pub fn cancel(&self) {
        self.shared.cancelled.store(true, Ordering::SeqCst);
        self.shared.generation.fetch_add(1, Ordering::SeqCst);
        let mut st = self.shared.lock_state();
        st.queue.clear();
        self.shared.cv.notify_all();
    }

    /// Drain finished thumbnails. On wasm (no workers) decodes up to
    /// 2 pending jobs inline. Stale-generation results are dropped.
    pub fn poll(&self) -> Vec<ThumbResult> {
        #[cfg(target_arch = "wasm32")]
        {
            self.pump_inline(2);
        }
        let gen = self.shared.generation.load(Ordering::SeqCst);
        let mut st = self.shared.lock_state();
        let all: Vec<ThumbResult> = std::mem::take(&mut st.out);
        all.into_iter().filter(|_| gen == self.shared.generation.load(Ordering::SeqCst)).collect()
        // NOTE: a job decoded before a rebuild carries a generation older
        // than `gen`; workers already re-check at decode time, and the
        // filter above drops anything produced across a rebuild boundary
        // that the UI no longer wants (no flicker of off-screen cells).
    }

    /// Decode up to `n` queued jobs synchronously (wasm / tests).
    pub fn pump_inline(&self, n: usize) {
        for _ in 0..n {
            let job = {
                let mut st = self.shared.lock_state();
                st.queue.pop() // LIFO
            };
            let Some(job) = job else { break };
            if self.shared.cancelled.load(Ordering::SeqCst) {
                break;
            }
            if job.generation != self.shared.generation.load(Ordering::SeqCst) {
                continue; // stale
            }
            if let Some(res) = decode_job(&job, &self.disk.dir) {
                let mut st = self.shared.lock_state();
                st.out.push(res);
            }
        }
    }

    /// Number of pending jobs (for tests / progress bars).
    pub fn pending(&self) -> usize {
        self.shared.lock_state().queue.len()
    }

    /// Procedural fallback tile (eiga test-card pattern) — never black (§4.7).
    /// Distinct from both the loading skeleton and the broken tile: this is
    /// the honest "indexed, no preview" state with a reason.
    pub fn fallback_tile(reason: &str) -> (Vec<u8>, String) {
        // 2×2 checker standing in for a drawn test card; the reason travels
        // with the tile so the UI can show "No preview — <reason>".
        let mut rgba = Vec::with_capacity(16);
        for i in 0..16 {
            rgba.push(if i % 8 < 4 { 120 } else { 200 });
        }
        (rgba, reason.to_string())
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn thumb_worker(shared: Arc<Shared>, cache_dir: PathBuf) {
    loop {
        let job = {
            let mut st = shared.lock_state();
            loop {
                if shared.cancelled.load(Ordering::SeqCst) {
                    // Wait until cancel clears / a new generation starts.
                    st = match shared.cv.wait(st) {
                        Ok(g) => g,
                        Err(e) => e.into_inner(),
                    };
                    st.queue.clear();
                    continue;
                }
                if let Some(j) = st.queue.pop() {
                    break j; // LIFO
                }
                st = match shared.cv.wait(st) {
                    Ok(g) => g,
                    Err(e) => e.into_inner(),
                };
            }
        };
        if shared.cancelled.load(Ordering::SeqCst) {
            continue;
        }
        if job.generation != shared.generation.load(Ordering::SeqCst) {
            continue; // stale after rebuild_visible / cancel
        }
        if let Some(res) = decode_job(&job, &cache_dir) {
            if job.generation == shared.generation.load(Ordering::SeqCst) {
                let mut st = shared.lock_state();
                st.out.push(res);
            }
        }
    }
}

/// Decode one job: disk → image decode / ffmpeg still → disk store → RGBA.
/// Returns `None` when undecodable (caller shows the declared tile).
/// Bounded reads (48 MB); never a black tile.
pub fn decode_job(job: &ThumbJob, cache_dir: &Path) -> Option<ThumbResult> {
    let disk_path = disk_path_for(cache_dir, &job.key);
    // Disk hit (key already has mtime — a hit is the current bytes).
    if let Ok(png) = std::fs::read(&disk_path) {
        if let Some((w, h, rgba)) = bytes_to_thumb(&png, job.edge) {
            return Some(ThumbResult {
                key: job.key.clone(),
                path: job.path.clone(),
                w,
                h,
                rgba,
                from_disk: true,
                video_frame: false,
            });
        }
    }
    // Image path (bounded read).
    let img_bytes = read_bounded(&job.path, MAX_DECODE_BYTES)?;
    if let Some((w, h, rgba)) = bytes_to_thumb(&img_bytes, job.edge) {
        // Store the *decoded* thumbnail as PNG so the next hit is cheap.
        store_thumb(cache_dir, &job.key, &img_bytes, job.edge);
        return Some(ThumbResult {
            key: job.key.clone(),
            path: job.path.clone(),
            w,
            h,
            rgba,
            from_disk: false,
            video_frame: false,
        });
    }
    // Video path: ffmpeg still (thumbs.rs video_thumb pattern).
    #[cfg(not(target_arch = "wasm32"))]
    {
        if let Some((w, h, rgba)) = video_thumb_job(&job.path, job.edge, cache_dir, &job.key) {
            return Some(ThumbResult {
                key: job.key.clone(),
                path: job.path.clone(),
                w,
                h,
                rgba,
                from_disk: false,
                video_frame: true,
            });
        }
    }
    None
}

fn read_bounded(path: &str, max: usize) -> Option<Vec<u8>> {
    use std::io::Read;
    let f = std::fs::File::open(path).ok()?;
    let mut buf = Vec::new();
    f.take(max as u64).read_to_end(&mut buf).ok()?;
    if buf.is_empty() {
        return None;
    }
    Some(buf)
}

fn bytes_to_thumb(bytes: &[u8], edge: u32) -> Option<(u32, u32, Vec<u8>)> {
    let img = image::load_from_memory(bytes).ok()?;
    let t = img.thumbnail(edge.max(1), edge.max(1)).to_rgba8();
    Some((t.width(), t.height(), t.into_raw()))
}

fn store_thumb(cache_dir: &Path, key: &str, src_bytes: &[u8], edge: u32) {
    let Ok(img) = image::load_from_memory(src_bytes) else { return };
    let t = img.thumbnail(edge.max(1), edge.max(1));
    let path = disk_path_for(cache_dir, key);
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let mut buf: Vec<u8> = Vec::new();
    let mut cur = std::io::Cursor::new(&mut buf);
    if t.write_to(&mut cur, image::ImageFormat::Png).is_ok() {
        let _ = std::fs::write(&path, &buf);
    }
}

/// ffmpeg `-ss 0.7` single frame → disk cache → RGBA thumbnail.
/// No ffmpeg / no valid frame → `None` (honest degrade, never black).
#[cfg(not(target_arch = "wasm32"))]
fn video_thumb_job(real_path: &str, edge: u32, cache_dir: &Path, key: &str) -> Option<(u32, u32, Vec<u8>)> {
    let out = std::process::Command::new("ffmpeg")
        .args(video_ffmpeg_args(real_path))
        .output()
        .ok()?;
    if !out.status.success() || out.stdout.is_empty() {
        return None;
    }
    let (w, h, rgba) = bytes_to_thumb(&out.stdout, edge)?;
    // Cache the *thumbnail* (not the raw frame) so repeat hits stay small.
    let path = disk_path_for(cache_dir, key);
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Some(img) = image::load_from_memory(&out.stdout) {
        let t = img.thumbnail(edge.max(1), edge.max(1));
        let mut buf: Vec<u8> = Vec::new();
        let mut cur = std::io::Cursor::new(&mut buf);
        if t.write_to(&mut cur, image::ImageFormat::Png).is_ok() {
            let _ = std::fs::write(&path, &buf);
        }
    }
    Some((w, h, rgba))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_changes_with_mtime_orientation_and_generation() {
        let a = cache_key("/p/a.jpg", 256, 100, 1, 0);
        assert_ne!(a, cache_key("/p/a.jpg", 256, 200, 1, 0), "mtime must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 256, 100, 6, 0), "orientation must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 256, 100, 1, 1), "edit_generation must be in the key");
        assert_ne!(a, cache_key("/p/a.jpg", 512, 100, 1, 0), "rung must be in the key");
        assert_eq!(a, cache_key("/p/a.jpg", 256, 100, 1, 0));
    }

    #[test]
    fn wanted_rung_never_overshoots() {
        assert_eq!(wanted_rung(60.0), 64);
        assert_eq!(wanted_rung(100.0), 128);
        assert!(wanted_rung(300.0) <= 512);
        assert_eq!(wanted_rung(99999.0), 4096);
    }

    #[test]
    fn big_pool_is_bounded_at_eight() {
        let mut pool: BigPool = Lru::new(8);
        for i in 0..20 {
            pool.insert(format!("k{i}"), vec![0u8; 4]);
        }
        assert_eq!(pool.len(), 8);
    }

    #[test]
    fn lru_evicts_least_recently_seen() {
        let mut c: Lru<u8> = Lru::new(2);
        c.insert("a".into(), 1);
        c.insert("b".into(), 2);
        let _ = c.get("a"); // a is now most-recently seen
        c.insert("c".into(), 3);
        assert!(c.get("b").is_none());
        assert!(c.get("a").is_some());
    }

    #[test]
    fn fanout_is_2_2() {
        let (a, b) = fanout("a1b2c3");
        assert_eq!((a.as_str(), b.as_str()), ("a1", "b2"));
    }

    #[test]
    fn disk_dir_is_shared_smart_files_cache() {
        let d = disk_dir();
        assert!(d.ends_with("smart-files/thumbs"), "got {}", d.display());
    }

    #[test]
    fn video_args_are_ss_0_7_single_frame() {
        let args = video_ffmpeg_args("/v/clip.mp4");
        assert!(args.windows(2).any(|w| w[0] == "-ss" && w[1] == "0.7"), "must seek to 0.7: {:?}", args);
        assert!(args.windows(2).any(|w| w[0] == "-frames:v" && w[1] == "1"));
        assert!(args.iter().any(|a| a == "png"), "png pipe: {:?}", args);
        assert!(args.iter().any(|a| a == "/v/clip.mp4"));
    }

    #[test]
    fn seen_dedupe_and_bounded() {
        let mut s = SeenLru::new();
        assert!(s.insert("k1".into()));
        assert!(!s.insert("k1".into()), "duplicate must dedupe");
        for i in 0..1100 {
            s.insert(format!("k{i}"));
        }
        assert!(s.len() <= SEEN_CAP, "seen leaked: {}", s.len());
    }

    fn tmp_dir(name: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("smart-photos-test-{name}-{}", std::process::id()));
        let _ = std::fs::create_dir_all(&d);
        d
    }

    fn make_png(w: u32, h: u32) -> Vec<u8> {
        let img: image::RgbImage = image::ImageBuffer::from_pixel(w, h, image::Rgb([200, 10, 30]));
        let mut buf = Vec::new();
        let mut cur = std::io::Cursor::new(&mut buf);
        img.write_to(&mut cur, image::ImageFormat::Png).unwrap();
        buf
    }

    #[test]
    fn visible_only_queue_never_decodes_off_screen() {
        let dir = tmp_dir("visible");
        let mut c = ThumbCache::new_inline(64, 8, dir);
        let mk = |p: &str| ThumbJob {
            path: p.into(),
            key: cache_key(p, 256, 1, 1, 0),
            rung: 256,
            edge: 256,
            generation: 0,
        };
        // Viewport shows only a.jpg — b/c are off-screen and never queued.
        c.rebuild_visible(vec![mk("/p/a.jpg")]);
        assert_eq!(c.pending(), 1);
        c.rebuild_visible(vec![mk("/p/b.jpg"), mk("/p/c.jpg")]);
        assert_eq!(c.pending(), 2, "rebuild replaces, never accumulates");
        c.cancel();
        assert_eq!(c.pending(), 0, "cancel must drop pending work");
    }

    #[test]
    fn decode_caches_png_to_disk_and_hits() {
        let dir = tmp_dir("diskhit");
        let src = tmp_dir("src");
        let file = src.join("a.png");
        std::fs::write(&file, make_png(8, 8)).unwrap();
        let path = file.to_string_lossy().to_string();
        let key = cache_key(&path, 256, 42, 1, 0);
        let job = ThumbJob { path: path.clone(), key: key.clone(), rung: 256, edge: 256, generation: 1 };
        let r = decode_job(&job, &dir).expect("png must decode");
        assert_eq!((r.w, r.h), (8, 8));
        assert!(!r.from_disk);
        assert_eq!(r.rgba.len(), (8 * 8 * 4) as usize);
        let on_disk = disk_path_for(&dir, &key);
        assert!(on_disk.exists(), "thumbnail must land on disk at {}", on_disk.display());
        // Source gone: disk hit still serves (mtime is in the key).
        std::fs::remove_file(&file).unwrap();
        let r2 = decode_job(&job, &dir).expect("disk hit must serve");
        assert!(r2.from_disk);
        assert_eq!(r2.rgba.len(), r.rgba.len());
    }

    #[test]
    fn undecodable_is_none_never_black() {
        let dir = tmp_dir("undec");
        let src = tmp_dir("srcu");
        let file = src.join("a.heic");
        std::fs::write(&file, b"not a real image").unwrap();
        let path = file.to_string_lossy().to_string();
        let job = ThumbJob {
            path: path.clone(),
            key: cache_key(&path, 256, 1, 1, 0),
            rung: 256,
            edge: 256,
            generation: 1,
        };
        assert!(decode_job(&job, &dir).is_none(), "HEIC bytes without a decoder must be None, never black");
        let (tile, reason) = ThumbCache::fallback_tile("HEIC decoder unavailable");
        assert_eq!(tile.len(), 16);
        assert!(reason.contains("HEIC"));
    }
}

