/// CPU per-pixel process on an RGB image. Pure and testable.
///
/// Order: saturation mix → exposure → contrast → warmth → blacks lift →
/// whites scale → dehaze → clarity (midtone contrast) → texture
/// (micro-contrast) → vignette. Short buffers are guarded (no panic).
pub fn process(src: &[u8], w: u32, h: u32, adj: &Adjust) -> Vec<u8> {
    if w == 0 || h == 0 {
        return Vec::new();
    }
    let pixels = (w * h) as usize;
    let avail = src.len() / 3;
    let n = pixels.min(avail);
    let mut out = vec![0u8; n * 3];
    let exp = 2f32.powf(adj.exposure);
    let con = adj.contrast;
    let sat = adj.saturation;
    let warm = adj.warmth;
    let vig = adj.vignette;
    for i in 0..n {
        let r = src[i * 3] as f32 / 255.0;
        let g = src[i * 3 + 1] as f32 / 255.0;
        let b = src[i * 3 + 2] as f32 / 255.0;
        let luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        let mix = |c: f32| (luma + (c - luma) * (1.0 + sat)).clamp(0.0, 1.0);
        let c1 = mix(r) * exp;
        let c2 = mix(g) * exp;
        let c3 = mix(b) * exp;
        let cc = |v: f32| ((v - 0.5) * (1.0 + con) + 0.5).clamp(0.0, 1.0);
        let mut nr = cc(c1 + warm * 0.10);
        let mut ng = cc(c2);
        let mut nb = cc(c3 - warm * 0.10);
        // Blacks: global lift/crush. Positive lifts the floor, negative
        // crushes it toward 0.
        let lift = adj.blacks * 0.08;
        nr = (nr + lift).clamp(0.0, 1.0);
        ng = (ng + lift).clamp(0.0, 1.0);
        nb = (nb + lift).clamp(0.0, 1.0);
        // Whites: highlight scale. Positive brightens, negative darkens.
        let wsp = 1.0 + adj.whites * 0.25;
        nr = (nr * wsp).clamp(0.0, 1.0);
        ng = (ng * wsp).clamp(0.0, 1.0);
        nb = (nb * wsp).clamp(0.0, 1.0);
        // Dehaze: haze is a wash toward grey — push away from 0.5
        // (global approx of the local haze removal, §7.3 honest note).
        let dh = 1.0 + adj.dehaze * 0.2;
        nr = ((nr - 0.5) * dh + 0.5).clamp(0.0, 1.0);
        ng = ((ng - 0.5) * dh + 0.5).clamp(0.0, 1.0);
        nb = ((nb - 0.5) * dh + 0.5).clamp(0.0, 1.0);
        // Clarity / texture: midtone + micro contrast (global proxy-size
        // approximation of the local operators — stated, not faked).
        let cl = 1.0 + adj.clarity * 0.3 + adj.texture * 0.15;
        nr = ((nr - 0.5) * cl + 0.5).clamp(0.0, 1.0);
        ng = ((ng - 0.5) * cl + 0.5).clamp(0.0, 1.0);
        nb = ((nb - 0.5) * cl + 0.5).clamp(0.0, 1.0);
        if vig.abs() > f32::EPSILON {
            let x = (i as u32 % w) as f32 / (w.max(1) as f32);
            let y = (i as u32 / w) as f32 / (h.max(1) as f32);
            let dx = x - 0.5;
            let dy = y - 0.5;
            let d = (dx * dx + dy * dy) * 4.0;
            let s = (d * d - 0.5 * d + 1.0).clamp(0.0, 1.0);
            let k = 1.0 - vig * s * 0.6;
            nr *= k;
            ng *= k;
            nb *= k;
        }
        out[i * 3] = (nr * 255.0).round().clamp(0.0, 255.0) as u8;
        out[i * 3 + 1] = (ng * 255.0).round().clamp(0.0, 255.0) as u8;
        out[i * 3 + 2] = (nb * 255.0).round().clamp(0.0, 255.0) as u8;
    }
    out
}

