fn read_range(&self, path: &str, offset: u64, max_bytes: usize) -> Option<Vec<u8>> {
    let real = self.real(path);
    let mut f = std::fs::File::open(real).ok()?;
    use std::io::{Read, Seek, SeekFrom};
    f.seek(SeekFrom::Start(offset)).ok()?;
    let cap = max_bytes.min(MAX_LOCAL_READ);
    let mut buf = vec![0u8; cap];
    let n = f.take(cap as u64).read(&mut buf).ok()?;
    buf.truncate(n);
    Some(buf)
}

