fn export(&self, src: &str, dest: &str, _quality: u8) -> Result<(), String> {
    // Honest bounded byte-copy (see the module note above). Chunked
    // read — never `usize::MAX` (that allocated a zero-buffer bomb).
    use std::io::{Read, Seek, SeekFrom};
    let real = self.real(src);
    let mut f = std::fs::File::open(&real).map_err(|e| e.to_string())?;
    f.seek(SeekFrom::Start(0)).map_err(|e| e.to_string())?;
    let mut bytes = Vec::new();
    let mut chunk = [0u8; 64 << 10];
    let mut total: u64 = 0;
    loop {
        let n = f.read(&mut chunk).map_err(|e| e.to_string())?;
        if n == 0 {
            break;
        }
        total += n as u64;
        if total > MAX_LOCAL_READ as u64 {
            return Err("source exceeds 48 MB export cap".into());
        }
        bytes.extend_from_slice(&chunk[..n]);
    }
    self.create_file(dest, &bytes)
}

