/// Format filter row (All / JPEG / PNG / HEIC / RAW / Video) driven by §4.5
/// kinds; demoted kinds are listed with their reason, never hidden silently.
pub fn format_options() -> Vec<(&'static str, &'static str)> {
    vec![
        ("All", "every kind"),
        ("JPEG", "decodable"),
        ("PNG", "decodable"),
        ("HEIC", "indexed — preview via embedded thumbnail or declared-unavailable"),
        ("RAW", "indexed + embedded JPEG preview"),
        ("Video", "ffmpeg stills when present"),
    ]
}

/// One picker row (name + containing dir + size for the footer).
#[derive(Clone, Debug)]
pub struct PickerRow {
    pub path: String,
    pub name: String,
    pub dir: String,
    pub size: u64,
    /// File extension (lowercased in `classify_extension`).
    pub ext: String,
}

/// Classify for the format filter row. `None` = not a media row.
pub fn classify_extension(ext: &str) -> Option<crate::model::PhotoKind> {
    crate::model::classify(ext)
}

fn format_matches(row: &PickerRow, format: &str) -> bool {
    let f = format.trim().to_ascii_lowercase();
    if f == "all" || f.is_empty() {
        return true;
    }
    let e = row.ext.trim().to_ascii_lowercase();
    match f.as_str() {
        "jpeg" | "jpg" => e == "jpg" || e == "jpeg" || e == "jfif",
        "png" => e == "png",
        "heic" | "heif" => e == "heic" || e == "heif",
        "raw" => crate::model::is_raw_ext(&e),
        "video" => classify_extension(&e) == Some(crate::model::PhotoKind::Video),
        _ => true, // unknown filter: do not hide silently — show all.
    }
}

/// Search + filter + sort for the picker grid (§9.3).
/// Scopes: *In this folder* (`search_everywhere == false`, substring over
/// the current dir rows the caller passed) vs *Everywhere* (caller passes
/// the recursive walk result; capped + reported by the caller per §9.7).
/// Hidden rows are dropped unless `show_hidden`. Never hides demoted kinds
/// silently — the format row lists each with its reason.
pub fn filter_visible(rows: &[PickerRow], state: &PickerState) -> Vec<usize> {
    let needle = state.query.trim().to_lowercase();
    let mut out: Vec<usize> = rows
        .iter()
        .enumerate()
        .filter(|(_, r)| state.show_hidden || !r.name.starts_with('.'))
        .filter(|(_, r)| {
            if !state.search_everywhere && r.dir != state.dir {
                return false;
            }
            if !needle.is_empty() && !r.name.to_lowercase().contains(&needle) {
                return false;
            }
            format_matches(r, &state.format)
        })
        .map(|(i, _)| i)
        .collect();
    match state.sort.as_str() {
        "size" => out.sort_by(|&a, &b| rows[b].size.cmp(&rows[a].size).then(rows[a].name.cmp(&rows[b].name))),
        "date" => out.sort_by(|&a, &b| rows[a].path.cmp(&rows[b].path)),
        _ => out.sort_by(|&a, &b| rows[a].name.cmp(&rows[b].name)),
    }
    out
}

