pub fn rebuild_visible(&mut self, jobs: Vec<ThumbJob>) {
    self.shared.generation.fetch_add(1, Ordering::SeqCst);
    self.shared.cancelled.store(false, Ordering::SeqCst);
    let gen = self.shared.generation.load(Ordering::SeqCst);
    // Rebuild, never accumulate: any pending job for a cell that
    // scrolled off-screen is dropped here, so off-screen cells are
    // never decoded.
    {
        let mut st = self.shared.lock_state();
        st.queue.clear();
    }
    for j in jobs {
        self.seen.insert(j.key.clone());
        let mut j = j;
        j.generation = gen;
        self.enqueue(j);
    }
}

