fn decode_caches_png_to_disk_and_hits() {
    let dir = tmp_dir("diskhit");
    let src = tmp_dir("src");
    let file = src.join("a.png");
    std::fs::write(&file, make_png(512, 512)).unwrap();
    let path = file.to_string_lossy().to_string();
    let key = cache_key(&path, 256, 42, 1, 0);
    let job = ThumbJob { path: path.clone(), key: key.clone(), rung: 256, edge: 256, generation: 1 };
